import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.DzI0iiKn.js";const i="/xuexitong-tutorial/images/settings.png",_=JSON.parse('{"title":"二、使用教程","description":"","frontmatter":{},"headers":[],"relativePath":"guide/usage.md","filePath":"guide/usage.md","lastUpdated":1791995933000}'),l={name:"guide/usage.md"};function h(n,a,s,d,c,u){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="二、使用教程" tabindex="-1">二、使用教程 <a class="header-anchor" href="#二、使用教程" aria-label="Permalink to &quot;二、使用教程&quot;">​</a></h1><blockquote><p><strong>省流版</strong></p><p>双击打开 <code>start</code> → 进入设置页面 → 填写相关信息并保存 → 返回主页点击开始刷课 → 脚本便会自动运行。<br> 如果有疑问，请看下面的详细介绍。</p></blockquote><h2 id="_1-启动程序" tabindex="-1">1. 启动程序 <a class="header-anchor" href="#_1-启动程序" aria-label="Permalink to &quot;1. 启动程序&quot;">​</a></h2><p>双击 <code>Start</code> 运行，运行后会出现一个弹窗，请仔细阅读用户须知，然后进入到设置页面填写相关信息。</p><h2 id="_2-配置设置" tabindex="-1">2. 配置设置 <a class="header-anchor" href="#_2-配置设置" aria-label="Permalink to &quot;2. 配置设置&quot;">​</a></h2><p><img src="'+i+'" alt="设置页面"></p><p>在设置页面中，第一项为<strong>配置设置</strong>，已经填充好了内容，不用修改。<br> 但如果在开始刷课后有提示浏览器相关的报错，就需要修改，具体操作见 <a href="/xuexitong-tutorial/guide/driver.html">如何安装正确的驱动</a>。</p><h2 id="_3-界面设置" tabindex="-1">3. 界面设置 <a class="header-anchor" href="#_3-界面设置" aria-label="Permalink to &quot;3. 界面设置&quot;">​</a></h2><p>第二项为<strong>界面设置</strong>，可根据个人喜好自行调整。</p><h2 id="_4-账号信息" tabindex="-1">4. 账号信息 <a class="header-anchor" href="#_4-账号信息" aria-label="Permalink to &quot;4. 账号信息&quot;">​</a></h2><p>第三项为<strong>账号信息</strong>：</p><ul><li>需要将您登录学习通的账号密码填写到输入框中；</li><li>然后填写要刷课的名称，可以添加课程，不过最多只能连续刷 3 门课程；</li><li>如果您不想使用账号密码登录，也可以在账号密码一栏中随意填写，在开始刷课后会提示您进行扫码登录。</li></ul><h2 id="_5-功能设置" tabindex="-1">5. 功能设置 <a class="header-anchor" href="#_5-功能设置" aria-label="Permalink to &quot;5. 功能设置&quot;">​</a></h2><p>第四项为<strong>功能设置</strong>，根据实际需求自行选择：</p><ul><li>前两项功能已经开发完毕；</li><li>最后一项还在开发中。</li></ul><h2 id="_6-关于自动刷课答题功能" tabindex="-1">6. 关于自动刷课答题功能 <a class="header-anchor" href="#_6-关于自动刷课答题功能" aria-label="Permalink to &quot;6. 关于自动刷课答题功能&quot;">​</a></h2><h3 id="_6-1-章节测验" tabindex="-1">6.1 章节测验 <a class="header-anchor" href="#_6-1-章节测验" aria-label="Permalink to &quot;6.1 章节测验&quot;">​</a></h3><p>第一个是“章节测验”，也就是章节中的测试题。点击下拉框有三个选择，根据自己的实际需求自行选择。</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>“随机答题”请谨慎选择，只有在章节测验不计入总成绩的情况下才能使用，否则成绩会很低。</p></div><p>如果您没有选择“不刷题”，则会弹出一个答完题后的设置，根据实际需求自行选择。</p><h3 id="_6-2-视频弹题" tabindex="-1">6.2 视频弹题 <a class="header-anchor" href="#_6-2-视频弹题" aria-label="Permalink to &quot;6.2 视频弹题&quot;">​</a></h3><p>第二个是视频中间弹出的题目的作答方式，也有两个选择，根据实际需求自行选择。</p><h3 id="_6-3-讨论部分" tabindex="-1">6.3 讨论部分 <a class="header-anchor" href="#_6-3-讨论部分" aria-label="Permalink to &quot;6.3 讨论部分&quot;">​</a></h3><p>第三个是讨论部分的完成方式，同样也有两个选择，根据实际需求自行选择。</p><h3 id="_6-4-倍数设置" tabindex="-1">6.4 倍数设置 <a class="header-anchor" href="#_6-4-倍数设置" aria-label="Permalink to &quot;6.4 倍数设置&quot;">​</a></h3><p>第四个是“倍数设置”，<strong>建议设置为 2 倍速</strong>，否则倍速过高，有可能会导致学习通已完成的任务点被清空。</p><h3 id="_6-5-跳过人脸" tabindex="-1">6.5 跳过人脸 <a class="header-anchor" href="#_6-5-跳过人脸" aria-label="Permalink to &quot;6.5 跳过人脸&quot;">​</a></h3><p>若课程需要刷脸才能进入，可开启此功能。开启后，第一次刷课需用手机扫码进行人脸验证，之后刷课就会自动跳过。</p><h3 id="_6-6-多端学习" tabindex="-1">6.6 多端学习 <a class="header-anchor" href="#_6-6-多端学习" aria-label="Permalink to &quot;6.6 多端学习&quot;">​</a></h3><p>开启后可同时刷多门课程，但<strong>请谨慎开启</strong>。</p><div class="danger custom-block"><p class="custom-block-title">风险提示</p><p>开启后有可能清空课程进度，甚至直接挂科。如果不是实在刷不完，还请老老实实一科一科地刷，一切后果自负。</p></div><h3 id="_6-7-秒过视频" tabindex="-1">6.7 秒过视频 <a class="header-anchor" href="#_6-7-秒过视频" aria-label="Permalink to &quot;6.7 秒过视频&quot;">​</a></h3><p>只有在视频可以拖动进度条的情况下生效。</p><h3 id="_6-8-防锁屏" tabindex="-1">6.8 防锁屏 <a class="header-anchor" href="#_6-8-防锁屏" aria-label="Permalink to &quot;6.8 防锁屏&quot;">​</a></h3><p>开启后在刷课的途中鼠标会左右跳动，防止电脑息屏影响刷课。当然，您也可以自行在电脑系统设置中关闭息屏功能。</p><h3 id="_6-9-定时刷课" tabindex="-1">6.9 定时刷课 <a class="header-anchor" href="#_6-9-定时刷课" aria-label="Permalink to &quot;6.9 定时刷课&quot;">​</a></h3><p>开启后在不关闭脚本窗口的情况下，可以根据您设定的时间，定时开始刷课或者结束刷课。</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>开启后脚本窗口一定不能关闭，否则无法正常定时刷课。</p></div><h2 id="_7-关于自动完成作业功能" tabindex="-1">7. 关于自动完成作业功能 <a class="header-anchor" href="#_7-关于自动完成作业功能" aria-label="Permalink to &quot;7. 关于自动完成作业功能&quot;">​</a></h2><h3 id="_7-1-ai-答题" tabindex="-1">7.1 AI 答题 <a class="header-anchor" href="#_7-1-ai-答题" aria-label="Permalink to &quot;7.1 AI 答题&quot;">​</a></h3><p>选择该功能后，将<strong>强制使用 DeepSeek AI</strong> 作为作业的答题方式，并自动保存答案。</p><h3 id="_7-2-选择作业" tabindex="-1">7.2 选择作业 <a class="header-anchor" href="#_7-2-选择作业" aria-label="Permalink to &quot;7.2 选择作业&quot;">​</a></h3><p>关于“选择作业”，也有两个选择：</p><ul><li><strong>手动选择</strong>：就是进入到作业，进入作业页面后，您需要手动点击要刷的作业，刷完该作业后程序会自动结束；</li><li><strong>自动选择</strong>：则默认从第 1 个作业开始，依次刷至最后一个。</li></ul><p>后面两个功能详情请见 <a href="#_6-5-跳过人脸">6.5</a>、<a href="#_6-6-多端学习">6.6</a>。</p><h2 id="_8-保存设置" tabindex="-1">8. 保存设置 <a class="header-anchor" href="#_8-保存设置" aria-label="Permalink to &quot;8. 保存设置&quot;">​</a></h2><p>填写完信息后<strong>务必点击“保存”</strong>，否则无法刷课。同样，修改任何信息都要进行保存，否则修改无效。</p><h2 id="_9-开始刷课" tabindex="-1">9. 开始刷课 <a class="header-anchor" href="#_9-开始刷课" aria-label="Permalink to &quot;9. 开始刷课&quot;">​</a></h2><p>保存好信息后返回“主页”，点击“开始刷课”后，脚本会自动打开浏览器登录您的学习通，进行自动刷课。</p><p>您也可以选择<strong>定时刷课</strong>，程序会自动按照您设定的时间开始或结束刷课。开启定时刷课后脚本的窗口不能关闭，否则无法定时开启刷课。</p><hr><p><a href="/xuexitong-tutorial/guide/preface.html">上一章：前言 ←</a> ｜ <a href="/xuexitong-tutorial/guide/driver.html">下一章：如何安装正确的驱动 →</a></p>',52)])])}const b=e(l,[["render",h]]);export{_ as __pageData,b as default};
